    t[151852] = { name = "Едикти Ґрала", fen = "The text on this scroll is of an ancient troll dialect and written using a special code. It could take a lifetime to unravel its complexity.", fua = "Текст на цьому сувої написаний стародавнім тролячим діалектом за допомогою особливого коду. На розгадування його складнощів може піти ціле життя." }
    t[151853] = { name = "Хвилі Могутності", fen = "Ancient spell work emblazons this scroll in a collection of symbols that are beyond your understanding.", fua = "Стародавня магія вкриває цей сувій набором символів, що поза межами твого розуміння." }
    t[151854] = { name = "Сувій Очищення", fen = "Only the spell's title is legible on this ancient scroll.", fua = "На цьому стародавньому сувої можна прочитати лише назву закляття." }
    t[151855] = { name = "Артефакт Ґрала", fen = "To the untrained eye this relic appears as nothing more than a decorative piece of ruin.", fua = "Недосвідченому оку ця реліквія здається не більш ніж оздобним уламком руїни." }
