    t[153185] = { name = "Сталева Коробка для Обіду", fen = "Wiping away the muck reveals a shining polished surface and well-oiled hinges. Someone kept this in immaculate condition before losing it.", fua = "Якщо стерти бруд, проступає блискуча полірована поверхня та добре змащені завіси. Хтось тримав її в бездоганному стані, перш ніж загубив." }
