    t[153566] = { name = "«Блискучий» Камінь", fen = "Dis one pretty. Pretty worthless! HAH! Not good for much.", fua = "Цей гарний. Гарно нікчемний! ХА! Мало для чого годиться." }
    t[153567] = { name = "«Гладкий» Камінь", fen = "Good for seeing hat you buy from Habdash. Dis called good salesogreship.", fua = "Гарний, щоб бачити капелюх, який ти купити в Габдаша. Це зватися добрий продажогрство." }
    t[153568] = { name = "«Спритний» Камінь", fen = "I met a small gnome who called it 'Airy-die-matic,' but that name dumb. Not test well with rock buyers. Dis good for throwin'.", fua = "Я зустрів малого ґнома, що назвав його «Аеро-дина-мічний», та ім'я дурне. Не сподобатися покупцям каменів. Цей гарний, щоб кидати." }
    t[153569] = { name = "«Твердий» Камінь", fen = "Top seller! Dis one best for bashing stuff. Good tool for home, for work, for anything!", fua = "Хіт продажів! Цей найкращий, щоб трощити всяке. Гарний інструмент для дому, для роботи, для всього!" }
    t[153570] = { name = "«Магічний» Камінь", fen = "Dis one specially magic. My chief told me so. Promise it magic or your money back!", fua = "Цей особливо магічний. Мій вождь так казати мені. Обіцяю, він магічний, або гроші назад!" }
