    t[157768] = { name = "Тіло Ковадла", fen = "The diaminium from which this is made has a mirror-like effect.", fua = "Діаміній, з якого це зроблено, має дзеркальний ефект." }
    t[157770] = "Бездоганний Пандаренський Дворучний Меч"
    t[157771] = { name = "Свята Вода", fen = "Blessed by the sea priests, this flask will purge even the most terrible of corruptions.", fua = "Благословлена морськими жерцями, ця настоянка очистить навіть найжахливішу скверну." }
    t[157772] = { name = "Королівський Клопіт", fen = "This letter has been carefully protected.", fua = "Цей лист дбайливо оберігали." }
    t[157774] = { name = "Документи на Коня", fen = "\"One (1) palomino horse of average height, build, and musculature.\"", fua = "«Один (1) кінь паломіно середнього зросту, статури та м'язистості.»" }
    t[157775] = { name = "Королівський Клопіт", fen = "This letter has been carefully protected.", fua = "Цей лист дбайливо оберігали." }
    t[157776] = { name = "Зловісне Послання", fen = "This letter appears well worn, but there could still be a chance the orders have not been carried out.", fua = "Цей лист має пошарпаний вигляд, та все ще є шанс, що накази не виконано." }
    t[157777] = { name = "Звіт із Зулдазару", fen = "This letter makes it clear that the naga are participating in the murky politics surfacing in Zuldazar. There is danger here.", fua = "Цей лист ясно дає зрозуміти, що наги беруть участь у темних політичних інтригах, що зринають у Зулдазарі. Тут чигає небезпека." }
    t[157778] = "Азеритовий Пил"
    t[157779] = { name = "Дино-Гранули для Малят", fen = "Bite-sized for small beaks and maws.", fua = "На один укус — для маленьких дзьобів і пащ." }
    t[157780] = { name = "Дино-Корм Вільного Вигулу", fen = "Complete nutrition for beasts of all shapes and sizes.", fua = "Повноцінне живлення для звірів усіх форм і розмірів." }
    t[157781] = { name = "Дино-Корм з Великими Шматочками", fen = "Perfectly balanced for maximum nutrition for fully grown beasts. The ingredient label just says \"VOODOO.\"", fua = "Ідеально збалансований для максимального живлення цілком дорослих звірів. На етикетці зі складом написано лише «ВУДУ»." }
    t[157782] = "Яйце Птеродакса"
    t[157783] = "Шлаковий Трощитель"
    t[157784] = { name = "Викрадені припаси", fen = "Grain, trinkets, torches. The tools of humanity, so easily taken.", fua = "Збіжжя, дрібнички, смолоскипи. Надбання людей, яке так легко в них забрати." }
    t[157785] = { name = "Чарівна Паличка Перетворення", fen = "\"If found, please return to Polymorph Pam in Bridgeport.\"", fua = "«Якщо знайдете, поверніть, будь ласка, Пам Перетворниці в Мостопорті.»" }
    t[157786] = { name = "Свіжовискубане Перо", fen = "Straight from the source.", fua = "Прямо з першоджерела." }
    t[157788] = "Яйце Саурида"
    t[157792] = { name = "Позолочене Ікло Річкового Звіра", fen = "So smooth and gilded... Surely someone would love this for their collection?", fua = "Таке гладеньке й позолочене... Хтось напевно хотів би додати його до своєї колекції?" }
    t[157793] = { name = "Ритуальний Порошок", fen = "Old powder that Shinga claims is the key to stopping Kel'vax.", fua = "Старий порошок, який, за словами Шинги, є ключем до зупинення Кел'вакса." }
    t[157794] = { name = "Лусочка Пернатої Гадюки", fen = "So bright and shiny... Surely someone would love this for their collection?", fua = "Така яскрава й блискуча... Хтось напевно хотів би додати її до своєї колекції?" }
    t[157797] = { name = "Перлина Мерзенної Луски", fen = "So beautiful and luminescent... Surely someone would love this for their collection?", fua = "Така прекрасна й сяйлива... Хтось напевно хотів би додати її до своєї колекції?" }
