    t[157801] = { name = "Хвіст Сталепащі", fen = "So ugly and scaly... Surely someone would love this for their collection?", fua = "Такий бридкий і лускатий... Хтось напевно хотів би додати його до своєї колекції?" }
    t[157802] = { name = "Реліквія Назватана", fen = "So ancient and tarnished... Surely someone would love this for their collection?", fua = "Така прадавня й потьмяніла... Хтось напевно хотів би додати її до своєї колекції?" }
