    t[162660] = { name = "Полірований Щит", fen = "The strong steel appears to have turned away many blows, but not the most critical one.", fua = "Схоже, міцна криця відбила багато ударів, але не найфатальніший із них." }
    t[162661] = { name = "Понівечений Череп", fen = "There appears to be a small stump of wax atop it. What foul rituals were conducted in the name of unholy masters?", fua = "Згори на ньому видніється маленький наплив воску. Які ж огидні ритуали проводили в ім'я нечестивих володарів?" }
    t[162662] = { name = "Гравірована Маска", fen = "The strange beak appears to be eaten away by some foul concoction.", fua = "Дивний дзьоб, схоже, роз'їла якась мерзенна суміш." }
    t[162663] = { name = "Зламаний Наконечник Списа", fen = "The wood attached to this sinuous blade is unlike any you have seen.", fua = "Деревина, до якої прикріплено цей звивистий клинок, не схожа ні на що, бачене вами раніше." }
    t[162664] = { name = "Пом'ятий Нагрудник", fen = "A sickly sweet odor is still present on the breastplate.", fua = "На нагруднику досі тримається нудотно-солодкий запах." }
    t[162665] = "Шабля з Грозосталі"
    t[162666] = { name = "Подертий Мішок", fen = "This bag once appears to have once been festooned with small charms. All of the chains are now broken.", fua = "Схоже, колись цю торбу прикрашали дрібні амулети. Тепер усі ланцюжки порвані." }
    t[162667] = { name = "Поховальна Урна Фарракі", fen = "Desperate offering for a peaceful afterlife.", fua = "Розпачлива офіра заради мирного потойбіччя." }
    t[162668] = { name = "Креслення: Закляттєвий Клинок Доблесного Воїна", fen = "Teaches you how to craft an Honorable Combatant's Spellblade more efficiently.", fua = "Навчає вас ефективніше виготовляти Закляттєвий Клинок Доблесного Воїна." }
    t[162669] = { name = "Креслення: Закляттєвий Клинок Доблесного Воїна", fen = "Teaches you how to craft an Honorable Combatant's Spellblade more efficiently.", fua = "Навчає вас ефективніше виготовляти Закляттєвий Клинок Доблесного Воїна." }
    t[162670] = { name = "Креслення: Штормосталева Шабля", fen = "Teaches you how to craft a Stormsteel Saber more efficiently.", fua = "Навчає вас ефективніше виготовляти Штормосталеву Шаблю." }
    t[162671] = { name = "Зламаний Арбалет", fen = "The mechanism is completely unusable. What manner of creature could do this?", fua = "Механізм повністю непридатний. Яка ж істота могла таке вчинити?" }
    t[162672] = "Чаклунські Намистини Знахарки"
    t[162673] = "Зав'язаний Булінь"
    t[162674] = { name = "Тріснутий Шолом", fen = "Silence seems to boom out of this hollowed helm.", fua = "Здається, з цього порожнього шолома лунає тиша." }
    t[162675] = "Гросбух Ешвейнів"
    t[162676] = { name = "Подерті Хутра", fen = "Whoever wore these into battle must have been strong indeed.", fua = "Хто б не носив їх у бою, він напевно був справді сильним." }
    t[162677] = { name = "Тупі Метальні Ножі", fen = "Perfectly balanced, these have not found their mark for some time.", fua = "Ідеально збалансовані, проте вже певний час не влучали в ціль." }
    t[162678] = { name = "Багряний Ціп", fen = "Covered in dried blood. But whose?", fua = "Вкритий засохлою кров'ю. Але чиєю?" }
    t[162679] = { name = "Пістоль з Осічкою", fen = "Soaked through and through. This has fired its last shot.", fua = "Наскрізь промоклий. Він зробив свій останній постріл." }
    t[162680] = { name = "Знищений Нашийник", fen = "A faithful friend, now lost along with its master.", fua = "Вірний друг, що тепер згинув разом зі своїм господарем." }
    t[162681] = { name = "Зігнутий Серп", fen = "Still bloody. Perhaps its owner had the last laugh after all.", fua = "Досі скривавлений. Можливо, його власник усе ж сміявся останнім." }
    t[162682] = { name = "Потьмянілий Довгий Меч", fen = "Once wielded with conviction and righteousness. Now discarded, lost, forgotten.", fua = "Колись його тримали з переконанням і праведністю. Тепер відкинутий, загублений, забутий." }
