    t[163085] = { name = "Цибулева Низка", fen = "Drustvar superstition suggests wearing onions about the neck will ward off evil spirits.", fua = "Друстварське повір'я твердить, що цибуля на шиї відганяє злих духів." }
    t[163087] = { name = "Торбина Криваво-Червоних Апельсинів", fen = "Opening the satchel reveals dozens of soft oranges covered in white and green mold.", fua = "Відкривши торбину, ви бачите десятки м'яких апельсинів, укритих білою та зеленою цвіллю." }
    t[163088] = "Цілком Звичайна Мітла"
    t[163089] = { name = "Люлька з Довгим Цибухом", fen = "Sharks and ships are carefully worked into this intricately carved pipe.", fua = "На цій майстерно вирізьбленій люльці дбайливо викарбувані акули й кораблі." }
    t[163090] = { name = "В'ялена Хвиле-Трава", fen = "Pirates on the Great Sea prize all manner of vices, particularly fine pipe weed.", fua = "Пірати Великого Моря цінують усілякі пороки, надто ж добірне люлькове зілля." }
    t[163091] = { name = "Самоцвітна Підзорна Труба", fen = "When a Kul Tiran becomes captain of their own vessel, they are gifted a spyglass worked with precious gems.", fua = "Коли кул-тіранець стає капітаном власного судна, йому дарують підзорну трубу, оздоблену коштовними самоцвітами." }
    t[163092] = { name = "Вишитий Соколиний Каптур", fen = "This beautifully embroidered hood is used to keep the bird calm during training.", fua = "Цей чудово вишитий каптур використовують, щоб тримати птаха спокійним під час вишколу." }
    t[163093] = "Ритуальна Крейда Відьми"
    t[163094] = { name = "Сніжноягідний Берлінер", fen = "A crowd favorite, this beer hits you up front with sour before falling back into the familiar sweetness of snowberries that Kul Tirans come to favor.", fua = "Загальний улюбленець: це пиво спершу вражає кислинкою, а тоді переходить у знайому солодкість сніжних ягід, яку так полюбляють кул-тіранці." }
    t[163095] = { name = "Золотий Троль-Берсерк", fen = "A common children's toy, this one appears to be missing a leg.", fua = "Звичайна дитяча іграшка, у цієї, схоже, бракує ноги." }
    t[163096] = { name = "Ручне Дзеркало зі Свинцевого Скла", fen = "A durable hand mirror ideal for maintaining a clean shave while sailing the high seas.", fua = "Міцне ручне дзеркало, ідеальне, щоб голитися начисто під час плавання у відкритому морі." }
    t[163097] = { name = "Різьблена Подоба Кролика", fen = "Cursed effigies anchor the hexthrall; transforming gentle bunnies into bloodthirsty beasts.", fua = "Прокляті подоби закріплюють чаклунську владу, перетворюючи лагідних зайченят на кровожерних бестій." }
    t[163098] = { name = "Кьольш Пасатів", fen = "A perfect beer for sitting out on the dock, basking in the sunlight. Considerably crushable.", fua = "Ідеальне пиво, щоб посидіти на причалі, ніжачись у сонячному світлі. Винятково легко п'ється." }
