    t[163638] = { name = "Маєток Корлейн 12 Років", fen = "Crafted in the tradition of Drustvar whiskies, this spirit is bottled at cask strength to be highly flammable, should the need arise.", fua = "Створений за традиціями віскі Друствару, цей напій розливають у міцності бочки, тож за потреби він добре горить." }
    t[163639] = { name = "Аратор з Однієї Бочки", fen = "Bottled from the only cask remaining from the ancient Empire of Arathor, this spirit's age is impossible to measure.", fua = "Розлитий з єдиної бочки, що лишилася від стародавньої імперії Аратор, цей напій неможливо датувати за віком." }
    t[163640] = { name = "Хуанцзе Чистий Солод", fen = "A delicate dram from the Valley of the Four Winds. Its unique notes are said to be achieved by only using water gathered from the base of Huangtze Falls.", fua = "Витончений напій із Долини Чотирьох Вітрів. Кажуть, його неповторні нотки досягаються лише завдяки воді, набраній біля підніжжя водоспаду Хуанцзе." }
    t[163641] = { name = "Брунгільдарська Паморозь", fen = "Distilled from wood-fired grain and boasting a unique chill-filtering process, this spirit offers a balance of clean malt and smoke.", fua = "Перегнаний із зерна, висушеного на дров'яному вогні, та очищений за неповторною технологією холодної фільтрації, цей напій поєднує чистий солод і дим." }
    t[163642] = { name = "Гніздовище 8 Років, Солод Закрайнів", fen = "An untamed spirit with a grassy character owed to the use of wild grains which grow only near the peaks of the Hinterlands mountains.", fua = "Неприборканий напій з трав'янистим характером завдяки диким зернам, що ростуть лише поблизу вершин гір Закрайнів." }
    t[163643] = { name = "Гауствальд 25 Років, Бочка з Рунодерева", fen = "The magical properties of the Runewood provide a truly unique finish to this vrykul spirit.", fua = "Магічні властивості рунодерева надають цьому врайкульському напою справді неповторного післясмаку." }
    t[163644] = { name = "Швидкий Раптор-Альбінос", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
