    t[163649] = { name = "Кул-Тіраський Гарпун", fen = "Standard issue harpoon used by the Proudmoore military in their harpoon cannons.", fua = "Стандартний гарпун, що його військо Праудмурів використовує у своїх гарпунних гарматах." }
