    t[163714] = { name = "Заборонена Морська Пісня про Бадьорих Хлопців", fen = "The lyrics encourage the men to cheer up and act lively, but it is clear none of them are still alive.", fua = "Слова закликають хлопців підбадьоритися й бути жвавими, та ясно, що ніхто з них уже не живий." }
    t[163715] = { name = "Заборонена Морська Пісня про Лічбу Плодів", fen = "At first it appears to be a simple dock worker's song, but it occurs to you the worker is Death, collecting souls while wishing for the end of its own existence.", fua = "Спершу здається, що це проста пісенька портового вантажника, та згодом доходить, що цей вантажник — Смерть, яка збирає душі й сама прагне кінця власного існування." }
    t[163716] = { name = "Заборонена Морська Пісня про Пияцтво", fen = "At first glance, the shanty lyrics describe a crew playing some merry pranks on an inebriated crewmember. The more you think about the lyrics, the more disturbing it becomes.", fua = "На перший погляд слова пісні описують команду, що грає веселі жарти з п'яним товаришем. Та що більше думаєш над ними, то моторошнішими вони стають." }
    t[163717] = { name = "Заборонена Морська Пісня про Йосефа", fen = "The lyrics of this shanty detail the disgusting port-town exploits of a sailor apparently known as \"Joe\".", fua = "Слова цієї пісні докладно змальовують огидні портові пригоди моряка, відомого, схоже, під ім'ям «Джо»." }
    t[163718] = { name = "Заборонена Морська Пісня про Чорну Сферу", fen = "The lyrics of this shanty describe sailors' cruel treatment at the hands of a captain known as Blackball Bill.", fua = "Слова цієї пісні описують жорстоке поводження з моряками від рук капітана на прізвисько Чорнокуля Білл." }
    t[163719] = { name = "Заборонена Морська Пісня про Коня", fen = "The lyrics of this shanty predict the inevitable death of an ill-treated horse.", fua = "Слова цієї пісні провіщають неминучу загибель занедбаного коня." }
    t[163720] = { name = "Формула Росту Мілденголлів", fen = "Smells faintly of honey, lavender, and rotten eggs.", fua = "Ледь пахне медом, лавандою і тухлими яйцями." }
