    t[163745] = { name = "Гонг Візербарків", fen = "Tired of enthusiastic warriors' incessant gong-bonging, Zalas had this carried deep into the Witherbark caves.", fua = "Втомившись від невпинного бамкання гонга, яке здіймали запальні воїни, Залас наказав віднести його глибоко в печери Візербарків." }
