    t[164764] = { name = "Вістря Тризуба", fen = "The ferocious prongs would work as a vicious melee weapon. Combine with the Trident Haft.", fua = "Лютий гострий наконечник став би жорстокою зброєю ближнього бою. Поєднайте з Держаком Тризуба." }
    t[164766] = { name = "Чарувальний Жезл Івен", fen = "Drust magic causes the rod to thrum with power. Can also serve as any lesser runed enchanting rod.", fua = "Магія друстів змушує жезл гудіти від сили. Може також правити за будь-який слабший рунічний чарувальний жезл." }
