    t[164778] = { name = "Безодній Скіпетр", fen = "One of the most cherished of tidesage artifacts. In the correct hands, it grants its user great power over the sea.", fua = "Один з найдорожчих артефактів припливних мудреців. У правильних руках він дарує власнику велику владу над морем." }
