    t[167002] = { name = "Креслення: Недоналаштовані Окуляри Корґі", fen = "A failed recipe for a device designed to make one's friends look adorable. In practice, it simply made one aware that corgis exist.", fua = "Невдалий рецепт пристрою, призначеного робити друзів чарівними. На практиці він лише дав усвідомити, що корґі існують." }
    t[167003] = { name = "Креслення: Рукавиці-Прихватки зі Справжнього Заліза", fen = "Instructions on how to craft True Iron Oven Mitts. An addendum at the bottom reads \"... not practical, very heavy, stiff, and poor heat protection.\"", fua = "Інструкція з виготовлення Рукавиць-Прихваток зі Справжнього Заліза. Доповнення внизу гласить: «...непрактичні, дуже важкі, цупкі й погано захищають від жару»." }
    t[167004] = { name = "Креслення: Ультрапідсилювач Часу Мод. 2", fen = "Incomplete notes on how to craft an Ultra Time Enhancer MK 2. Under the function heading, it reads \"Allows the wearer to move through time at the rate of one second for every real world second.\"", fua = "Незавершені нотатки про те, як виготовити Ультрапідсилювач Часу Мод. 2. Під заголовком призначення написано: «Дозволяє носієві рухатися крізь час зі швидкістю одна секунда на кожну секунду справжнього світу»." }
