    t[168124] = { name = "Схованка з Воєнними Ресурсами", fen = "Contains 500 War Resources.", fua = "Містить 500 воєнних ресурсів." }
    t[168125] = { name = "Рунний Камінь Троса", fen = "Gorak Tul was the first on Azeroth to use the stone to weave difficult and powerful enchantments.", fua = "Ґорак Тул був першим на Азероті, хто використав цей камінь, щоб плести складні й могутні зачарування." }
    t[168126] = { name = "Чіпка Лозяна Рука", fen = "The strongest golems of the Heartsbane Coven manage to retain some life even after being destroyed.", fua = "Найсильніші големи Серцезгубного Шабашу зберігають дрібку життя навіть після знищення." }
    t[168127] = { name = "Залишкова Сутність Друстів", fen = "Present in many of the ancient drust enemies, and more concentrated in those within Waycrest Manor.", fua = "Присутня в багатьох прадавніх ворогах-друстах, а ще більш концентрована в тих, що в Маєтку Вейкрест." }
    t[168128] = { name = "Сутність Величного Лоа", fen = "Rezan served the Zandalari kings for millennia.", fua = "Резан служив зандаларським королям тисячоліттями." }
    t[168129] = { name = "Сутність Тролячої Династії", fen = "Dazar was the first and Rastakhan will not be the last.", fua = "Дазар був першим, а Растахан не буде останнім." }
    t[168130] = { name = "Сутність Глибин", fen = "Kraken like Viq'Goth survived in the depths long before the races even dipped their toes in the seas.", fua = "Кракени на кшталт Вік'Ґота виживали в глибинах ще задовго до того, як народи вперше занурили пальці в моря." }
    t[168131] = { name = "Сутність Пісків", fen = "Sethraliss' sacrifice in Vol'dun saved Azeroth's fate but doomed her lush jungle home.", fua = "Жертва Сетраліс у Вол'дуні врятувала долю Азероту, та прирекла її буйну джунглеву домівку." }
    t[168132] = "Всипана Діамантами Підзорна Труба Світа"
    t[168133] = { name = "Неочищена Азеритова Жеода", fen = "The glowing heart of Azerokk.", fua = "Сяйливе серце Азерокка." }
    t[168134] = { name = "Дрібний Азеритовий Порошок", fen = "It's tough to find it in powder form, but Ashvane Company employees who handle Azerite may have some.", fua = "Його важко знайти у вигляді порошку, проте він може бути в працівників Компанії Ешвейн, які мають справу з азеритом." }
    t[168135] = { name = "Кров Титана", fen = "Contained within some of the largest manifestations of Azerite.", fua = "Міститься в деяких із найбільших проявів азериту." }
    t[168136] = "Кулак Азерокка"
    t[168137] = { name = "Інструменти Точного Благословення", fen = "The blessings bestowed on Kul Tiran ships by the Tidesage Council have to be super precise to work. We need that precision when tempering the hammer if we don't want to crack Azeroth.", fua = "Благословення, які Рада Припливних Мудреців дарує кул-тіранським кораблям, мають бути дуже точними, щоб діяти. Така точність потрібна нам і при загартуванні молота, якщо ми не хочемо розколоти Азерот." }
    t[168138] = { name = "Дух Подоланого", fen = "The spirits of the different rare beasts of Kul Tiras and Zandalar are won through valiant combat.", fua = "Духи різних рідкісних звірів Кул-Тіраса й Зандалара здобуваються у звитяжному бою." }
    t[168139] = { name = "Довга Велична Жила", fen = "The sinews still stretching across risen devilsaur are unrivaled in durability and timbre.", fua = "Жили, що досі натягнуті на воскреслих дияволозаврах, не мають рівних за міцністю й звучанням." }
    t[168140] = { name = "Прадавній Кров'яний Пігмент", fen = "Found within the blood of the great world threats roaming Kul Tiras and Zandalar.", fua = "Міститься у крові великих світових загроз, що блукають Кул-Тірасом і Зандаларом." }
    t[168141] = { name = "Закутий у Лід Прадавній Кров'яний Пігмент", fen = "It is slowly melting.", fua = "Він повільно тане." }
    t[168142] = { name = "Згустіле Міазма", fen = "The tainted blood of the Underrot has a unique property of not drying out naturally.", fua = "Зіпсута кров Гнилокореня має унікальну властивість не висихати природним чином." }
    t[168143] = { name = "Навмисно Потужне Зілля", fen = "The potions of the Heartsbane Coven in Waycrest Manor are of particular interest.", fua = "Зілля Серцезгубного Шабашу в Маєтку Вейкрест становлять особливий інтерес." }
    t[168144] = { name = "Надзвичайно Точна Колба", fen = "With a MOTHERLODE of potential, Razdunk's alchemists have to use precise instruments.", fua = "Зважаючи на ВЕЛЕТЕНСЬКИЙ потенціал, алхіміки Раздунка змушені користуватися точними інструментами." }
    t[168145] = { name = "Карафа Хитрого Розбійника", fen = "Jes Howlis has managed to hold on to this amazingly concealable decanter through many trials and incarcerations.", fua = "Джес Гавліс примудрилася зберегти цю напрочуд непомітну карафу попри численні випробування й ув'язнення." }
    t[168146] = { name = "Сфера Сангаурума", fen = "Priestess Alun'za saves the sphere for only the most important of rituals.", fua = "Жриця Алун'за береже цю сферу лише для найважливіших ритуалів." }
    t[168152] = { name = "Мініатюрне Силове Ядро", fen = "Found in sabertron models deployed in northwestern Stormsong and those in the Abandoned Junkheap.", fua = "Знаходиться у моделях шаблетронів, розгорнутих на північному заході Штормової Пісні, та на Покинутому Звалищі." }
    t[168153] = { name = "Важіль Повернення Монет", fen = "The one from the Coin-Operated Crowd Pummeler, will work perfectly as an on/off switch.", fua = "Цей із Монетного Молотильника Натовпу чудово підійде як перемикач." }
    t[168154] = { name = "Матриця Статичної Індукції", fen = "Only the largest lightning elementals within the Temple of Sethraliss can produce a stable matrix.", fua = "Лише найбільші стихії блискавки в Храмі Сетраліс здатні створити стабільну матрицю." }
    t[168155] = { name = "Прикорм", fen = "A pungent wad of mystery meat.", fua = "Смердючий жмут невідомого м'яса." }
    t[168157] = { name = "Мерехтлива Шкіра Вугра", fen = "Covered in slime, the skin sparkles and shines.", fua = "Вкрита слизом шкіра виблискує й сяє." }
    t[168158] = { name = "Зачарована Перлина", fen = "A pearl infused with ancient mana from the Well of Eternity.", fua = "Перлина, насичена прадавньою маною з Криниці Вічності." }
    t[168159] = "Прикорм"
    t[168160] = { name = "Самоцвітна Фігурка Скарабея", fen = "The previously animated scarab becomes a rigid figurine when touched.", fua = "Доти живий скарабей застигає в нерухому фігурку, щойно до нього торкнутися." }
    t[168162] = { name = "Хроносхованка з Тканиною", fen = "Contains cloth from the distant past, or perhaps the present, maybe the future?", fua = "Містить тканину з далекого минулого, а може, теперішнього, чи навіть майбутнього?" }
    t[168167] = { name = "Латунний Ключ", fen = "The grooves in the blade of the key have been worn with age.", fua = "Жолобки на борідці ключа стерлися від часу." }
    t[168168] = { name = "Позолочена Пір'їна", fen = "Found on the fabled golden serpents of Kings' Rest.", fua = "Знайдена на казкових золотих зміях Спочинку Королів." }
    t[168169] = { name = "Прадавній Сувій", fen = "A magical enchantment has preserved these ancient scrolls for thousands of years.", fua = "Магічне зачарування зберігало ці прадавні сувої тисячі років." }
    t[168170] = { name = "Таємний Фоліант", fen = "Written in ancient elvish, these tomes appear to contain priceless secrets of the arcane.", fua = "Написані прадавньою ельфійською, ці фоліанти, схоже, містять безцінні таємниці тайнознавства." }
    t[168171] = { name = "[PH] Objective Reward", fen = "It's a thing!", fua = "It's a thing!" }
    t[168173] = { name = "Водоростяна Ягода", fen = "These briny beauties blend savory and sweet flavors with a hint of tartness. They create a memorable wine and a tasty snack.", fua = "Ці солонуваті смаколики поєднують пікантні й солодкі смаки з ноткою терпкості. З них виходить незабутнє вино та смачна закуска." }
    t[168183] = { name = "Збирач Рідкісних Металів", fen = "Looks fancy, definitely stolen.", fua = "На вигляд вишуканий, точно крадений." }
