    t[168617] = { name = "Мінлива жила світу", fen = "This Worldvein has a much faster internal vibration, it will likely attract Azerite Shards much more frequently.", fua = "Ця жила світу має значно швидшу внутрішню вібрацію, тож, імовірно, притягуватиме скалки азериту набагато частіше." }
