    t[169227] = { name = "Опромінені Болти", fen = "Who built this? Did they survive the process?", fua = "Хто це збудував? Чи пережив він цей процес?" }
    t[169228] = { name = "Контейнер для Небезпечних Речовин", fen = "A clever solution to store hazardous byproducts internally.", fua = "Хитромудре рішення для зберігання небезпечних побічних продуктів усередині." }
    t[169229] = { name = "Ароматизатор Вихлопу", fen = "It smells like... candy?", fua = "Пахне... цукерками?" }
    t[169230] = { name = "Дзеркальна Накладка", fen = "You can see your reflection in this.", fua = "У ній можна побачити власне відображення." }
    t[169231] = { name = "Оптичний Привід Підміни", fen = "What didn't they want us to see?", fua = "Що вони не хотіли нам показати?" }
    t[169232] = { name = "Бракований Вибуховий Балон", fen = "Sometimes, faulty manufacturing can actually help.", fua = "Інколи дефекти виробництва навіть стають у пригоді." }
    t[169233] = { name = "Пружина Нескінченної Петлі", fen = "Its bounce is playful and fun.", fua = "Її стрибки грайливі й веселі." }
    t[169234] = { name = "Свіже Унагі", fen = "A little time on the grill is all you need... and maybe a little sauce.", fua = "Трохи часу на грилі — це все, що потрібно... ну й хіба що дещиця соусу." }
    t[169235] = { name = "Заплутана Пружинна Коробка", fen = "How does this work?", fua = "Як це працює?" }
    t[169236] = { name = "Замково-Засувний Спусковик", fen = "A good reminder to consider usability.", fua = "Гарне нагадування подбати про зручність." }
    t[169237] = { name = "Пульсівна Кулька", fen = "It sounds like a heartbeat.", fua = "Звучить як серцебиття." }
    t[169238] = { name = "Перероблений Радіоприймач", fen = "Magical elements can greatly enhance technical components, if leveraged properly.", fua = "Магічні елементи здатні значно посилити технічні складники, якщо їх правильно застосувати." }
