    t[169250] = { name = "Примітивне Столове Начиння", fen = "Is there anything more universal than food?", fua = "Чи є щось більш всеосяжне, ніж їжа?" }
    t[169251] = { name = "Прадавня Комаха", fen = "Preserved in amber, it's outlasted countless generations.", fua = "Збережена в бурштині, вона пережила незліченні покоління." }
    t[169252] = { name = "Звучна Перлина", fen = "Soft music emanates from it, but you can't make out the words.", fua = "Із неї лине тиха музика, але слів не розібрати." }
