    t[171320] = { name = "Осердя Порожнечі", fen = "Based on a design stolen from N'Zoth's forces, the power radiated by this dark crystal allows the wielder to craft powerful items.", fua = "Створене за схемою, викраденою у військ Н'Зота, темне сяйво цього кристала дозволяє власнику створювати потужні предмети." }
    t[171321] = { name = "[DNT] REUSE ME [MTMM]", fen = "Empowered with several shreds of nightmare, the crystal now hums with latent power, allowing the wielder to craft even more powerful items. Can serve as a Void Focus.", fua = "Зміцнений кількома клаптями жахіття, кристал тепер гуде прихованою силою, дозволяючи власнику створювати ще потужніші предмети. Може слугувати Осердям Порожнечі." }
    t[171322] = { name = "[DNT] REUSE ME [MTMM]", fen = "A torrent of manifested madness, the orb seems impossibly heavy and dark, but allows the wielder to craft yet more powerful items. Can serve as any lesser Void Focus.", fua = "Потік уявленого безумства; сфера здається неможливо важкою й темною, проте дозволяє власникові створювати ще могутніші речі. Може правити за будь-який слабший фокус Порожнечі." }
